export { anatomy, parts, type TooltipPart } from "./tooltip.anatomy";
export { connect } from "./tooltip.connect";
export {
  getContentEl,
  getContentId,
  getPositionerEl,
  getPositionerId,
  getTriggerEl,
  getTriggerId,
} from "./tooltip.dom";
export { machine } from "./tooltip.machine";
export { hideTooltip, isTooltipWarm, showTooltip } from "./tooltip.store";
export type {
  ResolvedTooltipMachineProps,
  TooltipApi,
  TooltipDismissDetails,
  TooltipMachineProps,
  TooltipOpenChangeDetails,
  TooltipSchema,
} from "./tooltip.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * Three parts, where the popover has ten, and the two it does not have are the
 * point rather than an omission.
 *
 * **No `arrow`.** A native desktop tooltip is a 49x18 rectangle
 * with two drop shadows and no spur at all, and touch platforms have no tooltip whatsoever —
 * so there is no geometry to read for one. Drawing an arrow here would mean
 * inventing a silhouette that was never published, and hanging it off a surface
 * eighteen pixels tall. A surface that needs to point at its anchor is a popover.
 *
 * **No `anchor`.** A tooltip describes the control it is attached to; there is no
 * case where it points at something else, and `aria-describedby` runs between
 * exactly those two nodes.
 *
 * Like the dialog and the popover, no `root`: the trigger stays where the author
 * wrote it and the surface is portalled, so the two are siblings.
 */
export type TooltipPart = "trigger" | "positioner" | "content";

export const anatomy: Anatomy<TooltipPart> = createAnatomy("tooltip").parts(
  "trigger",
  "positioner",
  "content",
);

export const parts: Record<TooltipPart, AnatomyPart> = anatomy.build();

export interface TooltipCssVars {
  // --- written ---
  /** Where the surface grows from, so a scale-in starts at the anchor. */
  "--sui-transform-origin": "<position>";
  /** Width of the anchor the surface is placed against. */
  "--sui-anchor-width": "<length>";
  /** Height of the anchor the surface is placed against. */
  "--sui-anchor-height": "<length>";
  /** Room left for the surface's width inside the boundary. */
  "--sui-available-width": "<length>";
  /** Room left for the surface's height inside the boundary. */
  "--sui-available-height": "<length>";
}

import { dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import type { Align, Side } from "../../positioner/compute-position";
import { parts } from "./tooltip.anatomy";
import { getContentId, getPositionerId, getTriggerId } from "./tooltip.dom";
import type { TooltipApi, TooltipSchema } from "./tooltip.types";

export function connect<T extends PropTypes>(
  service: Service<TooltipSchema>,
  normalize: NormalizeProps<T>,
): TooltipApi<T> {
  const { context, prop, send, scope } = service;

  const open = context.get("open");
  const disabled = prop("disabled");
  const state = open ? "open" : "closed";
  const placement = context.get("currentPlacement");
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];

  const contentId = getContentId(scope);
  const placementAttrs = { "data-side": side, "data-align": align };

  return {
    open,
    placement,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    /**
     * `aria-describedby` and never `aria-label`: a tooltip adds to the control's
     * name, it does not replace it. Published only while open, because that is
     * when the surface is in the tree — a dangling IDREF describes nothing.
     *
     * `disabled` is deliberately absent: the prop disables the tooltip, not the
     * control it hangs off, and a disabled control is exactly the one whose
     * tooltip explains why.
     */
    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: getTriggerId(scope),
        type: "button",
        "aria-describedby": open ? contentId : undefined,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
        onPointerEnter(event) {
          send({ type: "TRIGGER.POINTER_ENTER", pointerType: event.pointerType });
        },
        onPointerLeave() {
          send({ type: "TRIGGER.POINTER_LEAVE" });
        },
        onPointerDown() {
          send({ type: "TRIGGER.POINTER_DOWN" });
        },
        onFocus() {
          send({ type: "TRIGGER.FOCUS" });
        },
        onBlur() {
          send({ type: "TRIGGER.BLUR" });
        },
      }),

    /**
     * The floating element. `data-side` and `data-align` are absent here for the
     * popover's reason: the position effect writes them onto this node itself,
     * and an adapter rendering them too would fight it on every commit.
     */
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-state": state,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        ...placementAttrs,
        id: contentId,
        role: "tooltip",
        dir: context.get("surfaceDir") ?? prop("dir"),
        "data-state": state,
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "tooltip";

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

/** The floating element: what gets the translate, never the content. */
export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

/**
 * A tooltip is a popover the user never asked for, and every difference follows
 * from that one sentence.
 *
 * It is not opened by a click but by lingering, so the machine has a third state:
 * `opening` is the delay, where the pointer is on the trigger and nothing is
 * mounted yet. It is left by leaving, pressing, or the delay elapsing — and the
 * length of that delay is not this machine's to decide alone, because "has the
 * user already seen one of these" is a question about the whole page
 * (`tooltip.store.ts`).
 *
 * **It never takes focus, and nothing inside it is reachable.** `role="tooltip"`
 * has no interactive contents by definition, and the stylesheet gives the
 * surface `pointer-events: none` where the popover turns them back on — so there
 * is no hover to keep alive, no focus to trap, no tab to proxy, and no scrim.
 * What the popover spends two thirds of its machine on does not exist here.
 *
 * **Two openings, two rules.** A pointer opens it after a delay and only when it
 * is a real pointer — a touch `pointerenter` fires on tap, where there is no
 * hover to express intent, and opening there would hide the content behind a
 * gesture nothing advertises. A focus opens it immediately, but only under a
 * modality that warrants a ring: keyboard, or gamepad. That second rule is what
 * makes the tooltip reappear under a d-pad, where it stops being a nicety and
 * becomes the only label some controls have (research/components.md §166) — and
 * it is why the check is `isFocusVisible` rather than `:focus-visible`, which a
 * programmatic focus also matches on all three engines.
 */

import { addDomEvent } from "../../dom/event";
import { timeout } from "../../dom/raf";
import { resolveDir } from "../../dom/text-dir";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack, isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { trackLongPress } from "../../interaction/long-press";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { isFocusVisible, trackInputModality } from "../../nav";
import { trackPosition } from "../../positioner/track-position";
import type { Direction } from "../../types";
import { getContentEl, getContentId, getPositionerEl, getTriggerEl } from "./tooltip.dom";
import { hideTooltip, isTooltipWarm, showTooltip } from "./tooltip.store";
import type { TooltipSchema } from "./tooltip.types";

export const machine: Machine<TooltipSchema> = createMachine<TooltipSchema>({
  props({ props }) {
    return {
      defaultOpen: false,
      // motion.md §2.4. The long delay is the one that keeps a tooltip from
      // appearing under a pointer that is only passing through; the short one is
      // what the same pointer gets once it has demonstrably stopped to read.
      openDelay: 700,
      warmDelay: 300,
      // How long that concession outlives the surface. The annexe fixes the two
      // delays and not this, so it is a decision: long enough to cross a toolbar,
      // short enough that a tooltip read a minute ago grants nothing.
      warmDuration: 300,
      placement: "top",
      // Air, and all of it: with no arrow there is no depth to add on top, which
      // is why a tooltip sits visibly closer to its control than a popover does.
      gap: 8,
      offset: 0,
      flip: true,
      shift: true,
      padding: 8,
      strategy: "fixed",
      closeOnEscape: true,
      closeOnScroll: true,
      longPress: false,
      disabled: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "tooltip open",
      })),
      // Seeded from the prop rather than from a constant: the server renders
      // `data-side` from this, and the first paint has to agree with the markup.
      currentPlacement: bindable(() => ({ defaultValue: prop("placement") })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
    };
  },

  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackModality", "trackTouchGesture"],

  watch({ context, track, send }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
  },

  on: {
    "POSITION.SYNC": { actions: ["syncPlacement"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
  },

  states: {
    closed: {
      on: {
        "TRIGGER.POINTER_ENTER": { guard: "canHover", target: "opening" },
        "TRIGGER.FOCUS": { guard: "canFocus", actions: ["openTooltip"] },
        "TRIGGER.LONG_PRESS": { actions: ["openTooltip"] },
      },
    },

    // The delay, and nothing else: no surface is mounted, `open` is still false,
    // and every way out of it is a way of saying the linger did not happen.
    opening: {
      effects: ["waitOpenDelay"],
      on: {
        "DELAY.ELAPSED": { actions: ["openTooltip"] },
        "TRIGGER.FOCUS": { guard: "canFocus", actions: ["openTooltip"] },
        "TRIGGER.POINTER_LEAVE": { target: "closed" },
        "TRIGGER.POINTER_DOWN": { target: "closed" },
        "TRIGGER.BLUR": { target: "closed" },
      },
    },

    open: {
      // `holdVisibleSlot` last, and the order is a contract the interpreter
      // enforces by tearing down in reverse: the surface is placed and its layer
      // is registered before this tooltip claims the page's single slot and
      // closes whichever one held it, and the slot is released before any of
      // that comes back down.
      effects: [
        "trackSurfaceDir",
        "trackAnchorPosition",
        "trackDismissable",
        "dismissOnScroll",
        "captureIntents",
        "holdVisibleSlot",
      ],
      on: {
        "TRIGGER.POINTER_LEAVE": { actions: ["closeTooltip"] },
        "TRIGGER.POINTER_DOWN": { actions: ["closeTooltip"] },
        "TRIGGER.BLUR": { actions: ["closeTooltip"] },
        "CONTENT.SCROLL": { actions: ["closeTooltip"] },
        "CONTENT.DISMISS": { guard: "canDismiss", actions: ["invokeOnDismiss", "closeTooltip"] },
      },
    },
  },

  implementations: {
    guards: {
      isOpen: ({ context }) => context.get("open"),

      /**
       * A touch `pointerenter` arrives on tap, not on hover, and taking it would
       * open a tooltip the user cannot dismiss by moving away. Read off the event
       * rather than off the density: `pointerType` is the exact question, where
       * "is this a touch layout" is only a correlate of it.
       */
      canHover({ prop, event }) {
        if (prop("disabled") || event.type !== "TRIGGER.POINTER_ENTER") return false;
        return event.pointerType !== "touch";
      },

      canFocus: ({ prop, scope }) => !prop("disabled") && isFocusVisible(scope.getDoc()),

      /** Read live from the props, never snapshotted into the layer at install. */
      canDismiss({ prop, event }) {
        if (event.type !== "CONTENT.DISMISS") return false;
        return isEscapeLikeDismissal(event.reason) ? prop("closeOnEscape") : true;
      },
    },

    actions: {
      openTooltip({ context }) {
        context.set("open", true);
      },

      closeTooltip({ context }) {
        context.set("open", false);
      },

      setOpen({ context, event }) {
        if (event.type === "OPEN.SET") context.set("open", event.open);
      },

      invokeOnDismiss({ prop, event }) {
        if (event.type === "CONTENT.DISMISS") prop("onDismiss")?.({ reason: event.reason });
      },

      syncPlacement({ context, event }) {
        if (event.type === "POSITION.SYNC") context.set("currentPlacement", event.placement);
      },
    },

    effects: {
      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      /**
       * The surface is the one part that emits a `dir` nobody asked for,
       * and the portal is the whole reason. The adapter mounts it into
       * `document.body` (react/src/portal.tsx), outside whatever RTL region the
       * trigger sits in, and inheritance does not cross a portal — so the
       * direction has to be carried over explicitly. What was removed everywhere is the
       * ltr DEFAULT, not the attribute: a part still emits `dir` when the consumer
       * passes one. The default was the bug — emitting a direction nobody asked
       * for *overrode* the inheritance that already worked.
       *
       * Read from the anchor, never from the surface: the surface is in the body
       * and would only report the document's own direction back to itself. And in
       * an effect rather than in `connect`, so the server emits nothing and the
       * first client render has nothing to disagree with.
       */
      trackSurfaceDir({ prop, context, scope }) {
        context.set("surfaceDir", resolveDir(prop("dir"), getTriggerEl(scope)));
      },

      /**
       * Installed only where it was asked for, unlike `isDisabled` below which is
       * read live: five pointer listeners on every tooltip on the page is not a
       * price to pay for a prop that no consumer flips at runtime.
       */
      trackTouchGesture({ prop, scope, send }) {
        if (!prop("longPress")) return;
        return trackLongPress(getTriggerEl(scope), {
          isDisabled: () => prop("disabled"),
          onLongPress: () => send({ type: "TRIGGER.LONG_PRESS" }),
        });
      },

      /**
       * Always through a timer, even at zero. Sending synchronously from an
       * effect installer would transition out of `opening` while the interpreter
       * is still collecting this state's teardowns, and the cleanup it files
       * afterwards would belong to a state nothing is in any more.
       *
       * The clock comes off the trigger rather than off `scope.getWin()`, which
       * throws where there is no document: a machine driven with no page has no
       * tooltip to show, and that is a silence rather than a crash.
       */
      waitOpenDelay({ prop, scope, send }) {
        const doc = getTriggerEl(scope)?.ownerDocument;
        const win = doc?.defaultView;
        if (doc === undefined || win === null || win === undefined) return;
        const delay = isTooltipWarm(doc) ? prop("warmDelay") : prop("openDelay");
        return timeout(win, () => send({ type: "DELAY.ELAPSED" }), Math.max(0, delay));
      },

      trackAnchorPosition({ prop, scope, send }) {
        const positioner = getPositionerEl(scope);
        if (positioner === null) return;
        return trackPosition(getTriggerEl(scope), positioner, {
          placement: prop("placement"),
          gap: prop("gap"),
          offset: prop("offset"),
          flip: prop("flip"),
          shift: prop("shift"),
          padding: prop("padding"),
          // From the trigger, not from the surface: the surface is portalled into
          // `document.body` and would report the document direction, while the
          // alignment belongs to the region the trigger sits in.
          dir: resolveDir(prop("dir"), getTriggerEl(scope)),
          strategy: prop("strategy"),
          boundary: prop("boundary"),
          onPositioned: (result) => send({ type: "POSITION.SYNC", placement: result.placement }),
        });
      },

      /**
       * A layer even though nothing in it can be clicked, and that is the point:
       * the Escape that closes the tooltip must not also close the popover it is
       * sitting in. `dismissOnFocusOutside` is off — a tooltip opened by focus is
       * closed by the trigger's own blur, which fires first and says more.
       */
      trackDismissable({ prop, scope, send }) {
        return trackDismissableLayer(getContentEl(scope), {
          id: getContentId(scope),
          type: "tooltip",
          modal: false,
          parentId: prop("parentId"),
          exclude: () => [getTriggerEl(scope)],
          dismissOnFocusOutside: false,
          onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
        });
      },

      /**
       * On the document and in capture, because the scroller is whatever the
       * pointer happens to be over — including an ancestor the surface is not in.
       * Not routed through `CONTENT.DISMISS`: a scroll is not one of the four
       * dismissal reasons, and widening that union to say so would make every
       * other layer in the library answer a question it never asks.
       */
      dismissOnScroll({ prop, scope, send }) {
        if (!prop("closeOnScroll")) return;
        const doc = getContentEl(scope)?.ownerDocument;
        return addDomEvent(doc, "scroll", () => send({ type: "CONTENT.SCROLL" }), {
          capture: true,
          passive: true,
        });
      },

      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        const content = getContentEl(scope);
        if (host === null || host === undefined || content === null) return;
        const id = getContentId(scope);
        const stack = getLayerStack(content.ownerDocument);
        return host.pushScope((event) => {
          if (event.intent !== "back") return false;
          if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
          send({ type: "CONTENT.DISMISS", reason: "back" });
          return true;
        });
      },

      /**
       * The page's single tooltip slot, taken for as long as this state lasts.
       * An effect rather than an entry/exit pair, so the claim and the release
       * are the same object and cannot drift apart — and so the whole thing is
       * skipped where there is no surface, which is what a server render is.
       */
      holdVisibleSlot({ prop, scope, send }) {
        const doc = getContentEl(scope)?.ownerDocument;
        if (doc === undefined) return;
        const id = getContentId(scope);
        showTooltip(doc, id, () => send({ type: "OPEN.SET", open: false }));
        return () => hideTooltip(doc, id, prop("warmDuration"));
      },
    },
  },
});

/**
 * One tooltip at a time, and a family that stays warm.
 *
 * Two behaviours that no single machine can implement, because both are about
 * what the *other* tooltips on the page are doing:
 *
 * 1. **Only one is ever visible.** Opening one closes whichever was up. Without
 *    this, a pointer crossing a toolbar leaves a trail of surfaces behind it —
 *    each machine only knows its own trigger was left, and a leave that lands
 *    straight on the next trigger fires in an order nobody controls.
 * 2. **A family that has just shown one is warm**, and the next opens on the
 *    short delay instead of the long one (motion.md §2.4). The 700 ms is there to
 *    keep a tooltip from appearing under a pointer merely passing through; once
 *    the user has demonstrably stopped to read one, that argument is spent.
 *
 * Per document, not per module: an iframe or a popup window is a different page
 * with its own pointer, and a `WeakMap` keyed on the document is what the
 * modality tracker and the layer stack already do.
 *
 * State is a boolean plus a timer rather than a timestamp, so a test can drive it
 * with fake timers and never has to wait on a real clock.
 */

import { timeout } from "../../dom/raf";

interface Visible {
  readonly id: string;
  readonly close: VoidFunction;
}

interface Family {
  visible: Visible | null;
  warm: boolean;
  cancelCooldown: VoidFunction | undefined;
}

const families = new WeakMap<Document, Family>();

function familyOf(doc: Document): Family {
  const existing = families.get(doc);
  if (existing !== undefined) return existing;
  const created: Family = { visible: null, warm: false, cancelCooldown: undefined };
  families.set(doc, created);
  return created;
}

/**
 * Registers this tooltip as the visible one and closes the previous.
 *
 * The swap happens **before** the old one is told, so its own `hide` finds itself
 * no longer current and leaves `warm` alone — otherwise a handover would start a
 * cooldown for the tooltip that just opened.
 */
export function showTooltip(doc: Document, id: string, close: VoidFunction): void {
  const family = familyOf(doc);
  family.cancelCooldown?.();
  family.cancelCooldown = undefined;
  family.warm = false;
  const previous = family.visible;
  family.visible = { id, close };
  if (previous !== null && previous.id !== id) previous.close();
}

export function hideTooltip(doc: Document, id: string, warmFor: number): void {
  const family = familyOf(doc);
  if (family.visible?.id !== id) return;
  family.visible = null;
  family.cancelCooldown?.();
  family.cancelCooldown = undefined;

  const win = doc.defaultView;
  if (win === null || warmFor <= 0) {
    family.warm = false;
    return;
  }
  family.warm = true;
  family.cancelCooldown = timeout(
    win,
    () => {
      family.warm = false;
      family.cancelCooldown = undefined;
    },
    warmFor,
  );
}

/**
 * True while one is up as well as during the cooldown: moving from a trigger
 * whose tooltip is still open onto the next is the very case the short delay
 * exists for, and it is the one a cooldown started on close would miss.
 */
export function isTooltipWarm(doc: Document): boolean {
  const family = families.get(doc);
  if (family === undefined) return false;
  return family.warm || family.visible !== null;
}

import type { DismissReason } from "../../interaction/layer-stack";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Placement } from "../../positioner/compute-position";
import type { Direction, Rect } from "../../types";

export interface TooltipOpenChangeDetails {
  readonly open: boolean;
}

export interface TooltipDismissDetails {
  readonly reason: DismissReason;
}

export interface TooltipMachineProps {
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;

  // --- delays ----------------------------------------------------------------
  /**
   * How long a pointer has to rest on the trigger before the tooltip appears.
   * Long enough that a pointer merely crossing the control never opens one.
   */
  readonly openDelay?: number | undefined;
  /**
   * The delay once the family is warm — a tooltip is up, or one was up within
   * `warmDuration`. The long delay buys the user protection from tooltips they
   * did not ask for; once they have stopped to read one, they have asked.
   */
  readonly warmDelay?: number | undefined;
  /** How long the family stays warm after the last tooltip closed. */
  readonly warmDuration?: number | undefined;

  // --- positioning, handed straight to the positioner -------------------------
  readonly placement?: Placement | undefined;
  readonly gap?: number | undefined;
  readonly offset?: number | undefined;
  readonly flip?: boolean | undefined;
  readonly shift?: boolean | undefined;
  readonly padding?: number | undefined;
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly boundary?: (() => Rect) | undefined;

  // --- dismissal --------------------------------------------------------------
  /** Governs the gamepad `back` intent as well: B and Escape share one lock. */
  readonly closeOnEscape?: boolean | undefined;
  /** The anchor is moving out from under the surface; following it is worse. */
  readonly closeOnScroll?: boolean | undefined;

  /**
   * Opt-in, and off by default on purpose: a touch device has no hover, so a
   * tooltip there hides its content behind a gesture nothing advertises. Turn it
   * on only where the same information is reachable another way.
   */
  readonly longPress?: boolean | undefined;
  /** Disables the tooltip, not the trigger. */
  readonly disabled?: boolean | undefined;
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly parentId?: string | undefined;
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onOpenChange?: ((details: TooltipOpenChangeDetails) => void) | undefined;
  readonly onDismiss?: ((details: TooltipDismissDetails) => void) | undefined;
}

export interface ResolvedTooltipMachineProps extends TooltipMachineProps {
  readonly defaultOpen: boolean;
  readonly openDelay: number;
  readonly warmDelay: number;
  readonly warmDuration: number;
  readonly placement: Placement;
  readonly gap: number;
  readonly offset: number;
  readonly flip: boolean;
  readonly shift: boolean;
  readonly padding: number;
  readonly strategy: "absolute" | "fixed";
  readonly closeOnEscape: boolean;
  readonly closeOnScroll: boolean;
  readonly longPress: boolean;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface TooltipSchema extends MachineSchema {
  /** `opening` is the delay: the surface is not mounted and `open` is still false. */
  state: "closed" | "opening" | "open";
  props: ResolvedTooltipMachineProps;
  context: {
    /** The single source of truth; the state is a projection of it. */
    open: boolean;
    /** Where the surface actually landed — the preferred placement may have flipped. */
    currentPlacement: Placement;
    /**
     * The direction the portalled surface is drawn in, resolved from the anchor
     * when it opens. `null` until then — and on the server — which is what keeps
     * the first client render agreeing with the markup it hydrates.
     */
    surfaceDir: Direction | null;
  };
  event:
    | { type: "TRIGGER.POINTER_ENTER"; pointerType: string }
    | { type: "TRIGGER.POINTER_LEAVE" }
    | { type: "TRIGGER.POINTER_DOWN" }
    | { type: "TRIGGER.FOCUS" }
    | { type: "TRIGGER.BLUR" }
    | { type: "TRIGGER.LONG_PRESS" }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "CONTENT.SCROLL" }
    | { type: "DELAY.ELAPSED" }
    | { type: "POSITION.SYNC"; placement: Placement }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" };
  action: "openTooltip" | "closeTooltip" | "setOpen" | "invokeOnDismiss" | "syncPlacement";
  guard: "isOpen" | "canHover" | "canFocus" | "canDismiss";
  effect:
    | "trackModality"
    | "trackTouchGesture"
    | "waitOpenDelay"
    | "trackAnchorPosition"
    | "trackDismissable"
    | "trackSurfaceDir"
    | "dismissOnScroll"
    | "captureIntents"
    | "holdVisibleSlot";
}

export interface TooltipApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  /** Where the surface landed, which is not necessarily what was asked for. */
  readonly placement: Placement;
  setOpen(open: boolean): void;
  getTriggerProps(): T["button"];
  getPositionerProps(): T["element"];
  getContentProps(): T["element"];
}

export type {
  TooltipDismissDetails,
  TooltipMachineProps,
  TooltipOpenChangeDetails,
} from "@standarui/core/tooltip";
export { Tooltip, type TooltipComposedProps, type TooltipParts } from "./composed";
export {
  type TooltipApi,
  TooltipContent,
  TooltipPortal,
  type TooltipPortalProps,
  TooltipPositioner,
  TooltipRoot,
  type TooltipRootProps,
  TooltipTrigger,
  type UseTooltipProps,
  useTooltip,
  useTooltipContext,
} from "./tooltip";

/**
 * The tooltip in React: the popover's shape with two thirds of it removed.
 *
 * No backdrop, no arrow, no close trigger, no title or description — a tooltip
 * has one surface and nothing inside it a consumer can reach. Like the dialog and
 * the popover, the root renders no element: the trigger stays where the author
 * wrote it and the surface is portalled, so the two are siblings.
 *
 * The parenthood travels on the shared `layer-context`, which is what makes the
 * Escape inside a popover close the tooltip and not the popover.
 */

import type { Service } from "@standarui/core";
import * as tooltip from "@standarui/core/tooltip";
import { type ReactNode, type Ref, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { LayerProvider, useParentLayerId } from "../../layer-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { Portal, type PortalProps } from "../../portal";
import { type PresenceApi, usePresence } from "../../presence";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type TooltipApi = tooltip.TooltipApi<ReactPropTypes>;

export interface UseTooltipProps extends tooltip.TooltipMachineProps, MachineRuntimeProps {}

interface TooltipContextValue {
  readonly api: TooltipApi;
  readonly keepMounted: boolean;
  readonly content: PresenceApi;
}

const TooltipContext = createPartContext<TooltipContextValue>("Tooltip");

function useTooltipService(props: UseTooltipProps): Service<tooltip.TooltipSchema> {
  const parentLayerId = useParentLayerId();
  const host = useIntentScopeHost();

  return useMachine(tooltip.machine, {
    ...props,
    // `??` would override an explicit `null`, which is how a consumer says "this
    // surface answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
    parentId: props.parentId ?? parentLayerId,
  });
}

export function useTooltip(props: UseTooltipProps): TooltipApi {
  return tooltip.connect(useTooltipService(props), normalizeProps);
}

export function useTooltipContext(): TooltipApi {
  return TooltipContext.usePart("TooltipContext").api;
}

export interface TooltipRootProps extends UseTooltipProps {
  readonly keepMounted?: boolean | undefined;
  readonly children?: ReactNode;
}

export function TooltipRoot(props: TooltipRootProps): ReactNode {
  const { children, keepMounted, ...machineProps } = props;
  const service = useTooltipService(machineProps);
  const api = tooltip.connect(service, normalizeProps);
  const { motion } = useEnvironment();

  // See the note in `dialog.tsx`: `reduced` keeps the fade, only `none` removes it.
  const content = usePresence({ present: api.open, immediate: motion === "none" });

  const value: TooltipContextValue = { api, keepMounted: keepMounted === true, content };

  return (
    <LayerProvider layerId={tooltip.getContentId(service.scope)}>
      <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>
    </LayerProvider>
  );
}

/**
 * Read straight off the machine in the open direction, never off the presence:
 * the interpreter installs the open state's effects in the layout effect of the
 * very commit that opened it, and every one of them looks the surface up by id.
 * The presence only ever extends the mount past the close.
 */
function isMounted(context: TooltipContextValue): boolean {
  return context.keepMounted || context.api.open || context.content.present;
}

function usePresenceRef(
  presence: PresenceApi,
  consumer: Ref<HTMLElement> | undefined,
): Ref<HTMLElement> {
  return useMemo(() => composeRefs(presence.ref, consumer), [presence.ref, consumer]);
}

export const TooltipTrigger: (props: PartProps<"button">) => ReactNode = createPart(
  TooltipContext,
  {
    name: "TooltipTrigger",
    element: "button",
    props: (context) => context.api.getTriggerProps(),
  },
);

export interface TooltipPortalProps extends Omit<PortalProps, "children"> {
  readonly children?: ReactNode;
}

export function TooltipPortal(props: TooltipPortalProps): ReactNode {
  const { children, ...portalProps } = props;
  const context = TooltipContext.usePart("TooltipPortal");
  return isMounted(context) ? <Portal {...portalProps}>{children}</Portal> : null;
}

export function TooltipPositioner(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = TooltipContext.usePart("TooltipPositioner");

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getPositionerProps(),
    elementProps,
    children,
  });

  return isMounted(context) ? element : null;
}

export function TooltipContent(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = TooltipContext.usePart("TooltipContent");
  const composed = usePresenceRef(context.content, ref);

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getContentProps(),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  return isMounted(context) ? element : null;
}
